 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Locate a palette rectangle whose rows or columns repeat the same color sequence.
    palette = None
    key_cells = set()
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v]
        vals = [grid[r][c] for c in cols]
        if len(vals) >= 3 and len(set(vals)) >= 3:
            # Require contiguity and detect repeated identical rows.
            if cols == list(range(cols[0], cols[-1] + 1)):
                same = [rr for rr in range(h) if [grid[rr][c] for c in cols] == vals]
                if len(same) >= 2:
                    palette = vals
                    key_cells = {(rr, c) for rr in same for c in cols}
                    break
    if palette is None:
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c]]
            vals = [grid[r][c] for r in rows]
            if len(vals) >= 3 and len(set(vals)) >= 3 and rows == list(range(rows[0], rows[-1]+1)):
                same = [cc for cc in range(w) if [grid[r][cc] for r in rows] == vals]
                if len(same) >= 2:
                    palette = vals
                    key_cells = {(r, cc) for cc in same for r in rows}
                    break
    if not palette:
        return out
    # Use the footprint of the palette's middle color as the repeated object.
    anchor = palette[len(palette)//2]
    pts = [(r,c) for r in range(h) for c in range(w)
           if grid[r][c] == anchor and (r,c) not in key_cells]
    if not pts:
        return out
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    footprint = {(r-r0,c-c0) for r,c in pts}
    sh = r1-r0+1
    anchor_i = palette.index(anchor)
    # Remove palette key and all stacked object layers, then redraw from palette.
    for r,c in key_cells:
        out[r][c] = 0
    for r,c in pts:
        out[r][c] = 0
    for i,color in enumerate(palette):
        top = r0 + (i-anchor_i)*sh
        for dr,dc in footprint:
            rr,cc = top+dr,c0+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
